css='''*{box-sizing:border-box}body{margin:0;background:#dce7eb;color:#143b44;font-family:"Hiragino Kaku Gothic ProN","PingFang SC",Meiryo,sans-serif}h1,h2,h3,p,figure{margin:0}a{color:inherit;text-decoration:none}a:focus-visible{outline:3px solid #e29a61;outline-offset:5px}.lp{max-width:1200px;margin:auto;background:#f4f8f9}.nav{display:flex;justify-content:space-between;align-items:center;padding:30px 64px;border-bottom:1px solid #d5e2e5}.logo{display:flex;align-items:center;gap:12px}.logo .mark{display:grid;place-items:center;width:40px;height:44px;border-radius:11px 11px 20px 20px;background:#18464b;color:#fff;font:27px "Songti SC",serif}.logo strong{font-size:24px;letter-spacing:1px}.logo small{display:block;color:#638088;font-size:11px;margin-top:3px}.navlinks{display:flex;gap:24px;font-size:13px;color:#5b747c}.hero{padding:60px 64px 46px}.hero-grid{display:grid;grid-template-columns:1fr 1.13fr;gap:40px;align-items:center}.eyebrow{font-size:15px;font-weight:600;color:#16866e;letter-spacing:1px;margin-bottom:18px}h1{font-size:46px;line-height:1.55;letter-spacing:-1.8px;font-weight:650}.lede{font-size:18px;line-height:1.9;color:#59727c;margin-top:22px;max-width:470px}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:26px}.button{display:inline-block;padding:13px 21px;border-radius:6px;background:#146b5d;color:white;font-size:15px;font-weight:600}.button.secondary{color:#245d59;background:#e0eeeb}.screen{display:block;width:100%;height:auto;aspect-ratio:480/352;object-fit:contain;background:#000;border-radius:13px;box-shadow:0 18px 32px #0a2e3912}figcaption{font-size:13px;color:#66808a;margin-top:13px;line-height:1.7}.proof{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:42px;border-top:1px solid #cddde2;padding-top:27px}.proof strong{font-size:23px;color:#235b60}.proof p{font-size:13px;color:#62808a;margin-top:7px;line-height:1.7}.section{padding:56px 64px;border-top:1px solid #d7e3e6}.section.white{background:#fff}.section.green{background:#e8f2ee}.section h2{font-size:34px;line-height:1.55;font-weight:650;letter-spacing:-.9px}.intro{font-size:17px;line-height:1.85;color:#5d7780;margin-top:14px;max-width:950px}.two{display:grid;grid-template-columns:1fr 1fr;gap:32px;margin-top:30px}.screenhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;font-size:17px;font-weight:600}.screenhead span{font-weight:400;color:#69808a;font-size:13px}.shortline{margin-top:19px;display:flex;gap:20px;justify-content:space-between;flex-wrap:wrap;color:#3b6f69;font-size:16px}.callout{border-left:3px solid #c67747;background:#f7ece2;padding:15px 19px;font-size:14px;line-height:1.85;color:#815337;margin-top:22px}.inputrow{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:26px}.input{background:#edf4f5;border:1px solid #d4e3e6;border-radius:8px;padding:18px;text-align:center}.input b{font-size:20px}.input p{font-size:13px;color:#637e86;margin-top:7px;line-height:1.6}.guidegrid{display:grid;grid-template-columns:1.12fr 1fr;gap:42px;align-items:center;margin-top:28px}.points{display:flex;flex-direction:column;gap:26px}.point b{font-size:22px}.point p{color:#607b83;font-size:16px;line-height:1.85;margin-top:8px}.chips{display:flex;flex-wrap:wrap;gap:10px;margin-top:25px}.chip{padding:9px 15px;border-radius:5px;background:#deede7;color:#38695f;font-size:14px}.navflow{display:flex;justify-content:space-between;gap:16px;margin-top:29px;background:#ddeee7;padding:18px 23px;border-radius:8px;color:#245e53;font-size:17px;font-weight:600}.navflow i{font-style:normal;color:#a86134}.status{display:grid;grid-template-columns:1fr 1fr;gap:32px;margin-top:26px}.statusbox{border-top:3px solid #2b8872;padding-top:17px}.statusbox.pending{border-color:#c48b56}.statusbox h3{font-size:20px;margin-bottom:10px}.statusbox p{font-size:15px;line-height:1.95;color:#647a82}.close{background:#17454a;color:white;padding:43px 64px}.close h2{font-size:31px;line-height:1.6}.close p{font-size:14px;line-height:1.95;color:#bdd0d2;margin-top:17px}.last{margin-top:28px;padding-top:17px;border-top:1px solid #42666b;display:flex;justify-content:space-between;gap:20px;font:12px monospace;color:#a9c5ca}.srclinks{font-size:12px;color:#6b838c;margin-top:22px;line-height:1.8}.srclinks a{text-decoration:underline}@media(max-width:700px){.nav,.hero,.section,.close{padding:28px 22px}.navlinks{gap:12px;font-size:11px}.logo strong{font-size:19px}.logo small{font-size:9px}.hero-grid,.two,.guidegrid,.status{grid-template-columns:1fr;gap:24px}.eyebrow{font-size:13px}h1{font-size:36px}.section h2{font-size:28px}.lede,.intro{font-size:16px}.proof{gap:12px}.proof strong{font-size:18px}.proof p{font-size:12px}.inputrow{grid-template-columns:1fr 1fr}.input{padding:15px 10px}.input b{font-size:17px}.navflow{font-size:13px;padding:15px 10px;gap:8px}.screenhead{font-size:15px}.close h2{font-size:26px}.nav .mark{display:none}.last{font-size:10px}}'''
D={
'ja':dict(brand='Rokid Glasses 向け防災エージェント',links=['特長','行動ガイド','避難先'],eye='実際の Ink 画面で紹介する、開発中の試作版',title='ふだんは天気。<br>いざという時は、<br>行動を確認。',lede='いまいる地域の情報から、災害別の行動ガイド、避難先の確認まで。まもりが必要な情報を一画面にまとめます。',cta='避難先の画面を見る',cta2='特長を見る',herocap='日常のホーム画面。表示する地域・天気は訓練用データです。',proof=[('地域に合わせて','市町村を確認し、沿岸は別途確認。'),('一画面にまとめて','最初の行動と３つの要点。'),('日本語・中国語','７種類のガイドを端末内に収録。')],where='必要な情報を、いまいる場所から。',whereintro='GPS・音声や住所・地域一覧・郵便番号から市町村を確認。日常は天気を見ながら、災害時への備えを確認できます。',inputs=[('GPS','現在地の候補を確認'),('音声・住所','地名や住所から探す'),('地域一覧','都道府県から選ぶ'),('郵便番号','候補の市町村を確認')],switch='災害情報を受け取ると、<br>ホームの表示が切り替わる。',switchintro='地域に合った情報を取得すると、気温や降水確率の表示が災害名に切り替わります。新しく取得した重大な通報は、条件を満たすと詳細画面を自動で開きます。',before='ふだんのホーム',after='災害情報を表示したホーム',beforetag='天気と日ごろの備え',aftertag='津波・地震の訓練',switchcap='実際の Ink ホーム画面を、異なる訓練データで表示。',switchline=['天気の数値 → 災害名','場所とガイドはそのまま','通報の詳細へ'],switchfoot='災害時のホームは自動遷移前を一時停止して撮影。現在の前面表示で約１分ごとに確認する仕組みで、秒単位の緊急地震速報ではありません。',guide='最初にすることを、一画面で。',guideintro='状況に合ったガイドを開き、最初の行動と重要な３つの要点を確認。日本語・中国語を切り替えられます。',guidecap='津波ガイド：揺れから身を守り、その後すぐ高台へ。',points=[('最初の行動を大きく表示','何を優先するかを短い言葉で確認。'),('要点を同じ画面に','手動でページをめくらずに確認。'),('ガイドは端末内に収録','情報の取得が難しい時も、基本の行動を確認。')],chips=['地震','津波','土砂災害','大雨・洪水・高潮','台風・暴風','火山','日ごろの備え'],shelter='災害に合う避難先を探し、<br>ナビへの引き継ぎを確認。',shelterintro='実際の災害種別を選び、周辺の指定緊急避難場所を検索。候補の名称・住所・直線距離を確認してから、Hi Rokid で目的地を指定する方法を表示します。',flow=['災害種別を選ぶ','近くの候補を確認','ナビの起動方法へ'],s1='避難場所の候補を確認',s2='目的地をナビへ引き継ぐ',s1cap='実際に「GPSで周辺検索」を操作した Ink 画面。',s2cap='「ナビの起動方法」を押した後の Ink 画面。',shelternote='掲載地点・距離・標高は訓練用の架空データです。実際の避難先や安全な経路を示していません。ナビの自動起動は未接続で、目的地情報と起動方法の案内を表示します。',status='できることと、これからの検証。',st1='実装済みの画面・機能',st1p='所在地の確認／天気・災害情報の表示<br>日本語・中国語の行動ガイド<br>災害別の避難場所検索／ナビへの引き継ぎ案内',st2='接続・検証が必要な項目',st2p='本番の災害情報サービスと眼鏡実機<br>バックグラウンド通知の確実な配信<br>秒単位の緊急地震速報／ナビの自動起動',closing='情報を確認し、次の行動へ。',closingp='まもりは防災を補助する開発中の試作版です。公式の緊急情報に代わるものではありません。<br>警報が表示されないことは、安全や解除を意味しません。緊急時は自治体・気象庁・現場の指示に従ってください。',source='参考：気象庁・津波防災／国土地理院・指定緊急避難場所',foot='画面は Ink の実際の描画です。実際の眼鏡での撮影ではありません。'),
'zh':dict(brand='Rokid Glasses 日本防灾智能体',links=['产品特点','行动指南','避难地点'],eye='以真实 Ink 界面展示 · 开发原型',title='平时看天气，<br>灾时知行动。',lede='从所在地信息，到灾害应对指南，再到避难地点确认。まもり把关键信息与下一步，放进一屏。',cta='查看避难地导航',cta2='了解产品特点',herocap='日常首页。所在地与天气均为演练数据。',proof=[('结合所在地','先确认市町村，沿岸另行确认。'),('关键信息同屏','首要行动与三条要点集中呈现。'),('中日双语','七类指南随原生包保存在端内。')],where='从你所在的地方，了解需要的信息。',whereintro='通过 GPS、语音或地址、地区列表、日本邮编确认市町村。日常查看天气，也提前熟悉灾害应对方法。',inputs=[('GPS','确认当前位置候选'),('语音与地址','按地名或地址查找'),('地区列表','从都道府县逐级选择'),('日本邮编','确认对应市町村')],switch='取得灾害信息时，<br>首页切换显示重点。',switchintro='取得匹配所在地的信息后，天气数值切换为灾害名称。新的严重通报满足条件时，自动打开详情页。',before='日常首页',after='灾害信息首页',beforetag='天气与日常准备',aftertag='地震与海啸演练',switchcap='真实 Ink 首页：通过不同演练数据展示两种状态。',switchline=['天气数值 → 灾害名称','保留所在地与指南入口','进入通报详情'],switchfoot='灾害首页为自动跳转前的暂停截图。当前采用前台约每分钟检查机制，并非秒级地震预警。',guide='先做什么，一屏看清。',guideintro='打开对应情境指南，首要行动与三条关键要点同屏展示，并支持中文与日文切换。',guidecap='海啸指南：先防护摇晃，随后立即前往高地。',points=[('首要行动突出呈现','用短句说明当前应优先做什么。'),('三条要点同屏展示','无需手动翻页，就能查看关键要点。'),('基本指南保存在端内','信息难以取得时，也可查看基本行动。')],chips=['地震','海啸','滑坡泥石流','暴雨／洪水／风暴潮','台风／暴风','火山','日常准备'],shelter='按灾种查避难地，<br>再确认导航交接方式。',shelterintro='选择实际灾种，查询附近指定紧急避难场所。核对候选地点的名称、地址与直线距离后，查看如何在 Hi Rokid 导航中指定目的地。',flow=['选择实际灾种','查看附近候选','查看导航方式'],s1='查看避难地点候选',s2='确认目的地与导航交接',s1cap='实际点击“GPS 查询附近”后的 Ink 结果页。',s2cap='实际点击“查看导航方式”后的 Ink 页面。',shelternote='地点、距离和海拔均为演练用虚构数据，不代表真实避难地点或安全路线。当前自动启动导航尚未接通，界面提供目的地信息与导航启动方式。',status='已实现的功能，与下一步验证。',st1='已实现的界面与功能',st1p='所在地确认／天气与灾害信息展示<br>中日双语行动指南<br>按灾种查询避难地／导航交接说明',st2='仍需接通或验证',st2p='生产灾害信息服务与眼镜真机<br>后台通知可靠送达<br>秒级地震预警／自动启动导航',closing='读清信息，明确下一步。',closingp='まもり是防灾辅助开发原型，不能替代官方紧急信息。<br>无预警记录不等于安全或解除；紧急时遵循当地政府、气象厅及现场指示。',source='参考：气象厅海啸防灾／国土地理院指定紧急避难场所',foot='画面来自实际 Ink 渲染，非眼镜佩戴实拍。')}
for lang,d in D.items():
 suf='-zh' if lang=='zh' else ''
 def img(n):return 'screens/'+n+suf+'.png'
 proof=''.join(f'<div><strong>{a}</strong><p>{b}</p></div>' for a,b in d['proof']);inputs=''.join(f'<div class="input"><b>{a}</b><p>{b}</p></div>' for a,b in d['inputs']);points=''.join(f'<div class="point"><b>{a}</b><p>{b}</p></div>' for a,b in d['points']);chips=''.join(f'<span class="chip">{a}</span>' for a in d['chips']);flow='<i>→</i>'.join(f'<span>{a}</span>' for a in d['flow'])
 body=f'''<main class="lp"><header class="nav"><div class="logo"><span class="mark">守</span><div><strong>まもり MAMORI</strong><small>{d['brand']}</small></div></div><nav class="navlinks"><a href="#features">{d['links'][0]}</a><a href="#guide">{d['links'][1]}</a><a href="#shelters">{d['links'][2]}</a></nav></header>
<section class="hero"><div class="hero-grid"><div><p class="eyebrow">{d['eye']}</p><h1>{d['title']}</h1><p class="lede">{d['lede']}</p><div class="buttons"><a class="button" href="#shelters">{d['cta']}</a><a class="button secondary" href="#features">{d['cta2']}</a></div></div><figure><img class="screen" src="{img('ikeda-daily')}" alt="MAMORI Home"><figcaption>{d['herocap']}</figcaption></figure></div><div class="proof">{proof}</div></section>
<section class="section white" id="features"><p class="eyebrow">LOCATION</p><h2>{d['where']}</h2><p class="intro">{d['whereintro']}</p><div class="inputrow">{inputs}</div></section>
<section class="section"><p class="eyebrow">HOME → ALERT</p><h2>{d['switch']}</h2><p class="intro">{d['switchintro']}</p><div class="two"><figure><div class="screenhead">{d['before']}<span>{d['beforetag']}</span></div><img class="screen" src="{img('iwate-daily')}" alt="Daily home"></figure><figure><div class="screenhead">{d['after']}<span>{d['aftertag']}</span></div><img class="screen" src="{img('iwate-warning')}" alt="Alert home"></figure></div><div class="shortline">{''.join('<span>'+t+'</span>' for t in d['switchline'])}</div><figcaption>{d['switchcap']}</figcaption><div class="callout">{d['switchfoot']}</div></section>
<section class="section white" id="guide"><p class="eyebrow">ACTION GUIDE</p><h2>{d['guide']}</h2><p class="intro">{d['guideintro']}</p><div class="guidegrid"><figure><img class="screen" src="{img('iwate-guide')}" alt="Tsunami guide"><figcaption>{d['guidecap']}</figcaption></figure><div class="points">{points}</div></div><div class="chips">{chips}</div></section>
<section class="section green" id="shelters"><p class="eyebrow">SHELTER → NAVIGATION HANDOFF</p><h2>{d['shelter']}</h2><p class="intro">{d['shelterintro']}</p><div class="navflow">{flow}</div><div class="two"><figure><div class="screenhead">{d['s1']}</div><img class="screen" src="screens/shelters-{lang}.png" alt="Native Ink shelter results"><figcaption>{d['s1cap']}</figcaption></figure><figure><div class="screenhead">{d['s2']}</div><img class="screen" src="screens/navigation-{lang}.png" alt="Native Ink navigation handoff"><figcaption>{d['s2cap']}</figcaption></figure></div><div class="callout">{d['shelternote']}</div></section>
<section class="section white"><p class="eyebrow">PRODUCT STATUS</p><h2>{d['status']}</h2><div class="status"><div class="statusbox"><h3>{d['st1']}</h3><p>{d['st1p']}</p></div><div class="statusbox pending"><h3>{d['st2']}</h3><p>{d['st2p']}</p></div></div><p class="srclinks">{d['source']}<br><a href="https://www.jma.go.jp/jma/kishou/know/jishin/joho/tsunamiinfo.html">JMA</a> · <a href="https://www.gsi.go.jp/bousaichiri/hinanbasho">GSI</a></p></section>
<footer class="close"><h2>{d['closing']}</h2><p>{d['closingp']}<br>{d['foot']}</p><div class="last"><span>まもり / MAMORI</span><span>ROKID GLASSES · PROTOTYPE v0.2.2</span></div></footer></main>'''
 (O/f'product-long-{lang}.html').write_text(f'<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MAMORI · {d["brand"]}</title><style>{css}</style></head><body>{body}</body></html>')
print('Japanese and Chinese landing-page long layouts ready.')
